export type WalletTextLanguage = 'en' | 'fa' | 'ar' | 'tr';

const amountPattern = '([\\d۰-۹٠-٩,.٬،]+)';

// Only translate text generated by the payment workflow. Keep staff-written notes intact.
export function localizeWalletText(text: string, language: WalletTextLanguage): string {
  if (language === 'fa') return text;

  const debit = new RegExp(`مبلغ\\s+${amountPattern}\\s+دینار\\s+از\\s+کیف\\s+پول\\s+کسر\\s+شد`, 'g');
  const credit = new RegExp(`مبلغ\\s+اضافی\\s+${amountPattern}\\s+دینار\\s+به\\s+کیف\\s+پول\\s+اضافه\\s+شد`, 'g');
  const debitTexts = {
    en: (amount: string) => `${amount} IQD was deducted from the wallet`,
    ar: (amount: string) => `تم خصم ${amount} دينار عراقي من المحفظة`,
    tr: (amount: string) => `Cüzdandan ${amount} IQD düşüldü`,
  };
  const creditTexts = {
    en: (amount: string) => `${amount} IQD was added to the wallet`,
    ar: (amount: string) => `تمت إضافة ${amount} دينار عراقي إلى المحفظة`,
    tr: (amount: string) => `Cüzdana ${amount} IQD eklendi`,
  };
  return text
    .replace(debit, (_match, amount: string) => debitTexts[language](amount))
    .replace(credit, (_match, amount: string) => creditTexts[language](amount));
}

const approvalNotes = {
  'Payment approved by financial department - moving to warehouse': {
    en: 'Payment approved by financial department - moving to warehouse',
    fa: 'پرداخت توسط واحد مالی تأیید شد - انتقال به انبار',
    ar: 'تمت الموافقة على الدفع من القسم المالي - جارٍ النقل إلى المستودع',
    tr: 'Ödeme finans birimi tarafından onaylandı - depoya aktarılıyor',
  },
  'Grace period payment approved by financial department - awaiting manual warehouse transfer': {
    en: 'Grace period payment approved by financial department - awaiting manual warehouse transfer',
    fa: 'پرداخت سفارش مهلت‌دار توسط واحد مالی تأیید شد - در انتظار انتقال دستی به انبار',
    ar: 'تمت الموافقة على دفع الطلب خلال فترة السماح - بانتظار النقل اليدوي إلى المستودع',
    tr: 'Ek süreli ödeme finans birimi tarafından onaylandı - depoya manuel aktarım bekleniyor',
  },
} as const;

// The server persists the generated approval text alongside optional wallet
// adjustments. Translate only its exact leading phrase, never an arbitrary note.
export function localizeFinanceNote(note: string, language: WalletTextLanguage): string {
  let localized = note;
  for (const [original, translations] of Object.entries(approvalNotes)) {
    if (note === original || note.startsWith(`${original} - `)) {
      localized = translations[language] + note.slice(original.length);
      break;
    }
  }
  return localizeWalletText(localized, language);
}

// Wallet ledger descriptions for the same automatic payment adjustment.
export function localizeWalletTransactionDescription(text: string, language: WalletTextLanguage): string {
  if (language === 'fa') return text;
  const match = text.match(/^(تکمیل پرداخت سفارش|اضافه پرداخت سفارش)\s+(\S+)\s+-\s+(کسر از کیف پول|اعتبار به کیف پول)$/);
  if (!match) return text;
  const [, action, orderNumber] = match;
  const isDebit = action === 'تکمیل پرداخت سفارش';
  const translations = {
    en: isDebit ? `Order ${orderNumber} payment completed using wallet` : `Order ${orderNumber} overpayment credited to wallet`,
    ar: isDebit ? `إكمال دفع الطلب ${orderNumber} من المحفظة` : `إضافة المبلغ الزائد للطلب ${orderNumber} إلى المحفظة`,
    tr: isDebit ? `${orderNumber} numaralı siparişin ödemesi cüzdandan tamamlandı` : `${orderNumber} numaralı siparişin fazla ödemesi cüzdana eklendi`,
  };
  return translations[language];
}